const fs = require('node:fs'), path = require('node:path');
const ROOT = process.env.LOBOS_ROOT || path.resolve(__dirname, '..');
const P = path.join(ROOT, 'scripts', 'm0-criteria.json');
if (!fs.existsSync(P)) { console.error('报缺：那判据库逐字不在 ' + P); process.exit(2); }
const d = JSON.parse(fs.readFileSync(P, 'utf8'));
const rows = (d['$hostBoundAuditItems'] || []);
if (!rows.length) { console.error('报缺：那 12 条逐字不在 $hostBoundAuditItems 那一栏'); process.exit(2); }
let bad = 0, miss = 0, done = 0, asserted = 0;
const TIERS = ['原生等价', '近似', '不支持', '缺'];
for (const r of rows) {
  const m = r['三格机读'];
  if (!m) { console.error('  [红] ' + r['条目'] + ' 逐字没有那三格机读那一格（一族逐字没有落进可跑的形状）'); bad++; continue; }
  const cells = [m.actual, m.positive, m.negative];
  const names = ['actual', 'positive', 'negative'];
  const doneFlags = [];
  cells.forEach((v, i) => {
    //那「三格机读」那一格逐字是**取到的读数**那一个状态（取值域逐字只有
    //    「已核」与「缺」那两个）一条**人定的具体断言**逐字另落那「三格断言」那一格
    if (v === '已核') { done++; doneFlags.push(true); }
    else if (v === '缺') { miss++; doneFlags.push(false); }
    else { console.error('  [红] ' + r['条目'] + ' 的 ' + names[i] + ' 逐字是 ' + JSON.stringify(v) + '（那「三格机读」那一格逐字是**取到的读数**那一个状态、取值域逐字只有「已核」与「缺」）'); bad++; doneFlags.push(false); }
  });
  //两条**人定的具体断言**逐字逐条要能机械判（是 04 逐字落的、那 01 逐字钉的）
  const asserts = r['三格断言'] || {};
  for (const side of ['positive', 'negative']) {
    const a = asserts[side];
    if (typeof a !== 'string' || !a.trim()) { continue; }
    if (side === 'negative') {
      if (a.indexOf('不许') < 0 || a.indexOf('必须') < 0) {
        console.error('  [红] ' + r['条目'] + ' 的 negative 那一条断言逐字**不是**一条具体断言'
          + '（它逐字**要**含那「不许」与那「必须」、按 C-05 不猜填）'); bad++;
      } else { asserted++; }
    } else {
      if (a.indexOf('=>') < 0) {
        console.error('  [红] ' + r['条目'] + ' 的 positive 那一条断言逐字**不是**一条具体断言'
          + '（它逐字**要**钉死成一个具体的值、按 C-05 不猜填）'); bad++;
      } else { asserted++; }
    }
  }
  const tier = String(r['declared_tier 机读'] || '');
  if (TIERS.indexOf(tier) < 0) {
    console.error('  [红] ' + r['条目'] + ' 的 declared_tier 机读逐字是 ' + JSON.stringify(tier) + '（取值域逐字是那四个：' + TIERS.join(' / ') + '）'); bad++;
  }
  const allDone = doneFlags.every(f => f === true);
  if (!allDone && tier !== '缺') {
    console.error('  [红] ' + r['条目'] + ' 的三格机读逐字不全「已核」（那 actual=' + m.actual + ' positive=' + m.positive + ' negative=' + m.negative + '）'
      + '，那 declared_tier 机读逐字必须是「缺」、实得 ' + JSON.stringify(tier) + '（按 C-05 不许猜填）'); bad++;
  }
  if (allDone && tier === '缺') {
    console.error('  [红] ' + r['条目'] + ' 的三格机读逐字全「已核」、那 declared_tier 机读逐字**不该**是「缺」（按 R3 那一族逐字该算一档）'); bad++;
  }
  const s = String(r['S 值'] || '').match(/「\*\*(S[123])\*\*」/);
  if (!s) { console.error('  [红] ' + r['条目'] + ' 逐字没有那 S 值那一格（它逐字不可机读）'); bad++; }
}
console.log('  那 12 条逐条：三格已核 ' + done + ' 格、缺 ' + miss + ' 格、具体断言 ' + asserted + ' 格；档位取值域=' + TIERS.join('/') + '；形状不合 ' + bad + ' 处');
if (bad) { console.error('::error title=那 12 条逐条没有落进可跑的形状::' + bad + ' 处不合（判据库那一族那一层、规范那一层归 04）'); process.exit(1); }
console.log('那 12 条逐条逐字落进那可跑的形状、三格逐条**可机读**、那 declared_tier 逐字**可机读**');
